from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,collections,subprocess,sys
P=Path(__file__).resolve().parent
subprocess.run([sys.executable,str(P/'checkpoint.py')],check=True)
r=json.loads((P/'RESULT.json').read_text());assert r['full_checker_native_verified']==r['total']==23
scope={tuple(x[k] for k in ['baseline','operator','case_id']):x for x in json.loads((P/'SCOPE.json').read_text())};links=[];proposals=[]
def sha(f):
 with f.open('rb') as h:return hashlib.file_digest(h,'sha256').hexdigest()
for x in r['rows']:
 key=tuple(x['key']);d=Path(x['checker']).parent;root=P/(x['host']+'_evidence');freeze=root/'HOST_FREEZE.json';guard=json.loads((d/'GUARD_RUNNING.json').read_text());start=datetime.fromisoformat(guard['updated_at']).timestamp();assert freeze.stat().st_mtime<start
 assert (d/'1.generated.cpp').is_file() and (d/'1.kernel.txt').is_file()
 commands=[json.loads(l) for l in (d/'subprocess.jsonl').read_text().splitlines()];compiles=[c for c in commands if isinstance(c['argv'],list) and c['argv'][0]=='bisheng'];assert compiles
 assert all('--cce-aicore-arch=dav-c310' in c['argv'] and '-DREGISTER_BASE' in c['argv'] for c in compiles)
 post=json.loads((root/'POST_AUDIT.json').read_text());assert not post['changes']
 native=json.loads((d/'native.json').read_text());assert scope[key]['api']=='tilelang-ascend::'+native['api']
 links.append(dict(key=x['key'],host=x['host'],host_freeze=str(freeze),freeze_sha256=sha(freeze),freeze_time=freeze.stat().st_mtime,guard_process_start=start,freeze_leads_start_seconds=start-freeze.stat().st_mtime,post_audit=str(root/'POST_AUDIT.json'),generated_cpp_sha256=sha(d/'1.generated.cpp'),kernel_source_sha256=sha(d/'1.kernel.txt'),compile_argv=compiles,hardware=str(d/'DEVICE.json') if (d/'DEVICE.json').exists() else str(freeze),original_api=native['api']))
 proposals.append(dict(key=x['key'],status='ready_for_parent_review',accepted_added=0,existing_factory=scope[key]['factory'],original_api=scope[key]['api'],checker=x['checker'],guard=x['guard'],native_evidence=x['artifacts'],source_binding=str(d/'native.json'),private_run_directory=str(d),registration_performed=False))
(P/'PRESTART_LINK.json').write_text(json.dumps(links,indent=2));(P/'REGISTRATION_PROPOSAL.json').write_text(json.dumps(dict(accepted_added=0,rows=proposals),indent=2))
checks=json.loads((P/'CHECKS.json').read_text());checks.update(full_checker_pass=23,all_outputs_checked=23,input_preserved=23,original_seed_shape_dtype_match=23,guard_zero_selected=23,call_pointer_dladdr_maps_inode_elf_join=23,generated_cpp_and_device_binary_preserved=23,actual_compiler_matches_build_receipt=23,loaded_libgen_matches_original=23,host_freeze_precedes_process_start=23,all_selected_runs_compile_with_original_bisheng=True,post_audit_unchanged_files={h:json.loads((P/(h+'_evidence')/'POST_AUDIT.json').read_text())['checked_files'] for h in ['local','server1','server2']});(P/'CHECKS.json').write_text(json.dumps(checks,indent=2))
now=datetime.now(timezone.utc).isoformat();attempts=collections.Counter(str(json.loads(f.read_text())['returncode']) for f in P.glob('*.guard.json'))
delivery=dict(at=now,worker='dd2a166c28284b81',status='complete_23_full_checker_native_revalidation',scope=23,full_checker_native_verified=23,accepted_added=0,registered_added=0,by_host=dict(collections.Counter(x['host'] for x in r['rows'])),findings=['All 23 exact tilelang-ascend/operator/case_id keys passed the unchanged complete checker with original seed/shape/dtype and preserved inputs.','All selected runs have guard exit 0, actual call pointer/dladdr/maps/inode/ELF hash, generated kernel/C++ and extracted actual AICore binary sections.','All selected runs newly compiled through original public PTO/A5 path after host source/compiler/SDK freeze; actual loaded compiler matches build receipt and libgen matches clean upstream.','No kernel, compiler, checker, seed, tolerance, shared registry, parent ledger or memory modifications.'],attempt_exit_counts=dict(attempts),excluded_attempt_note='Initial local checker pass excluded because prestart collection was incomplete. Early VERSION/observer setup failures and five guard-75 waits are retained; final selected receipts supersede them. Fresh independent caches were used for two provenance closure reruns.',changed_files=['RESULT.json','DELIVERY.json','CHECKS.json','PRESTART_LINK.json','REGISTRATION_PROPOSAL.json','FILEHASHES.json','private runners/observers/CPU freeze and audit scripts','local_evidence/','server1_evidence/','server2_evidence/','per-attempt guard logs and receipts'],remaining_issues=['Parent review and formal registration; accepted_added remains 0. No performance claim or profiling requested.'],proof_index='RESULT.json',original_backend_admission='../ORIGINAL_PUBLIC_BACKEND_ADMISSION_20261027.json')
