for name in ['HEARTBEAT.json','LOCAL_HEARTBEAT.json','ROUTING_HEARTBEAT.json']:(P/name).write_text(json.dumps(dict(at=now,phase='complete',hosts=['local','server1','server2'],exactkeys_completed=23,active=[],accepted_added=0,actual_progress='23 full checker and native provenance chains complete; final artifacts archived'),indent=2))
